import { GridCount, GridTypeClassnames } from '../../types/common';

export function getGridClassName(grid?: GridCount): GridTypeClassnames | string {
  switch (grid) {
    case 1: {
      return GridTypeClassnames.grid1;
    }
    case 2: {
      return GridTypeClassnames.grid2;
    }
    case 3: {
      return GridTypeClassnames.grid3;
    }
    case 4: {
      return GridTypeClassnames.grid4;
    }
    case 5: {
      return GridTypeClassnames.grid5;
    }
    case '1-2': {
      return GridTypeClassnames.grid1_2;
    }
    case '2-1': {
      return GridTypeClassnames.grid2_1;
    }
    default: {
      return '';
    }
  }
}

export function loadScript(src: string): Promise<void> {
  // Share in-flight/settled load promises across bundles via window: aem-core can be
  // bundled into more than one clientlib on a page, so a module-scoped cache would not
  // dedupe between copies. Without this, a second copy could see another copy's freshly
  // appended <script> tag and resolve before it finishes loading — racing dependent
  // scripts (e.g. Highcharts modules running before the core) into "undefined" errors.
  const win = window as Window & {
    __acLoadScriptPromises?: Record<string, Promise<void> | undefined>;
  };
  const cache = win.__acLoadScriptPromises ?? (win.__acLoadScriptPromises = {});

  const cached = cache[src];
  if (cached) {
    return cached;
  }

  // A matching tag already exists but isn't tracked here (appended outside this loader).
  // Preserve the original best-effort behaviour — our own concurrent loads dedupe via the
  // shared cache above, so they never reach this branch.
  if (document.querySelector(`script[src="${src}"]`)) {
    return (cache[src] = Promise.resolve());
  }

  return (cache[src] = new Promise<void>((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.onload = () => resolve();
    s.onerror = reject;
    document.head.appendChild(s);
  }));
}

export function loadCss(href: string): Promise<void> {
  if (document.querySelector(`link[href="${href}"]`)) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const link = document.createElement('link');

    link.rel = 'stylesheet';
    link.href = href;

    link.onload = () => resolve();
    link.onerror = () => reject(new Error(`Failed to load css: ${href}`));

    document.head.appendChild(link);
  });
}
