import cn from 'classnames';

import { ContainerLayoutProps } from './container-layout.types';
import { getGridClassName } from '../../assets/utils/common';

import './container-layout.scss';

export function ContainerLayout({
  id,
  className,
  useLibClass = false,
  centered = false,
  fullWidth = false,
  contentWidth,
  bgColor,
  bgImage,
  children,
  grid,
  useAemGridTemplate = false,
}: ContainerLayoutProps) {
  const classname = cn(
    'container responsivegrid',
    { 'ds-brand-container': useLibClass },
    { 'mx-auto': centered },
    { 'max-w-full': fullWidth },
    { [`ds-content-width-${contentWidth}`]: contentWidth },
    getGridClassName(grid),
    className,
  );

  return (
    <div id={id} className={classname}>
      <div
        className="cmp-container"
        style={{
          backgroundColor: bgColor,
          backgroundImage: bgImage,
        }}
      >
        {useAemGridTemplate ? <div className="aem-Grid aem-Grid--12 aem-Grid--default--12">{children}</div> : children}
      </div>
    </div>
  );
}

export default ContainerLayout;
